## Quick example

```ts
import { Actor, state, event } from "@mantaq/core";
import { matches } from "@mantaq/sugar";

const idle = state("idle")();
const running = state("running")();

const start = event("START")();
const stop = event("STOP")();

const machine = new Actor({
  inputs: [start, stop],
  states: [idle, running],
  initial: idle,
  transitions: {
    idle: { START: () => ({ state: running }) },
    running: { STOP: () => ({ state: idle }) },
  },
});

machine.send(start.create());
matches(machine, "running"); // true
```

Actors are state machines. States are nodes, transitions are edges. Testing means walking the graph and asserting you land where expected.

## Simple Example: Traffic Light

States: `green` → `yellow` → `red` → `green` (cycle)
Events: `NEXT`

```ts
import { Actor } from "@mantaq/core";
import { state, event } from "@mantaq/core";
import { matches } from "@mantaq/sugar";

const green = state("green")();
const yellow = state("yellow")();
const red = state("red")();

const next = event("NEXT")();

function createTrafficLight() {
  return new Actor({
    inputs: [next],
    outputs: [],
    internal: [],
    states: [green, yellow, red],
    initial: green,
    context: {} as {},
    effects: {},
    transitions: {
      green: { NEXT: () => ({ state: yellow }) },
      yellow: { NEXT: () => ({ state: red }) },
      red: { NEXT: () => ({ state: green }) },
    },
  });
}
```

